INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP001', 'knowledge', 'K001', 'なぜ人は呼吸するのか', 'physiology', '呼吸は、体に必要な酸素を取り込み、体で生じた二酸化炭素を外に出す働きです。
肺から血液、細胞へとつながる流れを学びます。酸素は、細胞が栄養からATPをつくる過程で使われます。酸素そのものがATPに変わるという意味ではありません。', ARRAY['P01','P03','P160']::text[], '[{"issue_id":"I001","rule":"酸素は、細胞が栄養からATPをつくる過程で使われます。"},{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"}]'::jsonb, '{}', ARRAY['なぜ人は呼吸するのか','基礎','酸素','二酸化炭素','なぜ呼吸するの？','息をする目的は？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP002', 'knowledge', 'K002', '呼吸の流れを4つに分けて理解する', 'physiology', 'この教材では、空気の出入り、肺胞でのガス交換、血液による運搬、細胞でのエネルギー産生という流れで学びます。
肺だけで完結するのではなく、血液循環や細胞の働きまでつなげて理解するための整理です。', ARRAY['P02']::text[], '[{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"}]'::jsonb, '{}', ARRAY['呼吸の流れを4つに分けて理解する','全体像','換気','ガス交換','ATP','呼吸は肺だけの働き？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP003', 'knowledge', 'K003', '換気とは', 'physiology', '換気は、空気を肺に出し入れすることです。
肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。', ARRAY['P02','P03','P037','P151','P152','P154','P155']::text[], '[{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"},{"issue_id":"I017","rule":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。"},{"issue_id":"I031","rule":"一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。"},{"issue_id":"I032","rule":"肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。"},{"issue_id":"I034","rule":"図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。"}]'::jsonb, '{}', ARRAY['換気とは','肺','横隔膜','吸気','呼気','換気って何？','肺は自分で動くの？','肺は筋肉なの？','呼吸筋という筋肉が肺にあるの？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP004', 'knowledge', 'K004', '肺胞で起こるガス交換', 'physiology', '肺胞では、酸素が血液へ入り、二酸化炭素が血液から肺胞へ移ります。
原稿が「外呼吸」と呼ぶ部分です。肺に空気を出し入れする換気と、その空気と血液の間でガスを交換する働きを区別して学びます。', ARRAY['P02','P03','P034','P156','P161']::text[], '[{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"},{"issue_id":"I037","rule":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。"}]'::jsonb, '{}', ARRAY['肺胞で起こるガス交換','肺胞','外呼吸','毛細血管','肺胞は何をしているの？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP005', 'knowledge', 'K005', '酸素はどうやって全身に届くのか', 'physiology', '取り込んだ酸素は主に赤血球のヘモグロビンと結び付き、血液の流れで全身へ運ばれます。
心臓はその血液を送り出すポンプとして働きます。呼吸と循環を一緒に理解するための項目です。', ARRAY['P03','P039','P162','P163','P164']::text[], '[{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"},{"issue_id":"I036","rule":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。"},{"issue_id":"I037","rule":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。"}]'::jsonb, '{}', ARRAY['酸素はどうやって全身に届くのか','赤血球','ヘモグロビン','心臓','酸素は血液で運ばれる？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP006', 'knowledge', 'K006', 'ATPとは', 'cell_energy', 'ATPは、細胞が活動に必要なエネルギーをやり取りするために使う分子です。
酸素がそのままATPに変わるわけではありません。酸素は、栄養から得たエネルギーを使ってATPを作る過程を支えます。原稿の「エネルギー通貨」は、この役割を伝えるたとえです。', ARRAY['P01','P04','P043','P165','P168']::text[], '[{"issue_id":"I001","rule":"酸素は、細胞が栄養からATPをつくる過程で使われます。"},{"issue_id":"I020","rule":"ATPの再利用の説明を残し、「1日に体重の約100倍」の数値は根拠確認まで掲載しない。"},{"issue_id":"I038","rule":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。"}]'::jsonb, '{}', ARRAY['ATPとは','ATP','エネルギー','酸素','ATPって何？','酸素がATPになるの？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP007', 'knowledge', 'K007', 'ミトコンドリアの役割', 'cell_energy', 'ミトコンドリアは、多くの細胞でATPの産生を担う細胞内の構造です。
原稿では「細胞の発電所」とたとえています。吸い込んだ酸素と細胞内の働きを結び付けて学ぶための説明です。', ARRAY['P07','P044','P167','P168','P170']::text[], '[{"issue_id":"I003","rule":"ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。"},{"issue_id":"I004","rule":"多くの細胞では、ミトコンドリアがATPの産生に関わります。"},{"issue_id":"I005","rule":"37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。"},{"issue_id":"I021","rule":"糖からエネルギーを取り出す過程は複数あります。反応の場所と酸素の必要性を分けた図に描き直し、監修を受ける。"},{"issue_id":"I038","rule":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。"}]'::jsonb, '{}', ARRAY['ミトコンドリアの役割','細胞','ミトコンドリア','ATP','ミトコンドリアと呼吸はどう関係する？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP008', 'knowledge', 'K008', '二酸化炭素と呼吸調節', 'co2', '二酸化炭素は体外へ排出される一方、呼吸の調節にも関係しています。
脳などが血液中の二酸化炭素や酸素に関する情報を受け取り、必要に応じて呼吸を調整します。二酸化炭素だけを唯一の呼吸スイッチと考えないことが大切です。', ARRAY['P05','P06','P049','P183']::text[], '[{"issue_id":"I007","rule":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。"},{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"}]'::jsonb, '{}', ARRAY['二酸化炭素と呼吸調節','CO₂','呼吸中枢','二酸化炭素は不要なもの？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP009', 'knowledge', 'K009', '二酸化炭素と血液のpH', 'co2', '教材では、二酸化炭素の変化が血液の酸性・アルカリ性のバランスに関わると説明しています。
この項目は教材の生理学的説明です。自分の呼吸の感覚だけから血液のpHを推定したり、呼吸法でpHを調整しようとする指示には使いません。', ARRAY['P05']::text[], '[{"issue_id":"I007","rule":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。"}]'::jsonb, '{}', ARRAY['二酸化炭素と血液のpH','pH','酸塩基','二酸化炭素とpHは関係する？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP010', 'knowledge', 'K010', 'ボーア効果とは', 'co2', '教材では、二酸化炭素が増えpHが低下する組織側で、ヘモグロビンが酸素を放しやすくなることをボーア効果として紹介しています。
働いている組織への酸素の受け渡しを理解する項目です。「CO₂は多いほどよい」という意味には使いません。', ARRAY['P05']::text[], '[{"issue_id":"I007","rule":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。"}]'::jsonb, '{}', ARRAY['ボーア効果とは','ボーア効果','ヘモグロビン','酸素','ボーア効果をやさしく説明して']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP011', 'knowledge', 'K011', '呼吸数を観察する', 'observation', '原稿では、安静にして、いつも通りの呼吸を1分間数える観察を紹介しています。
回数と一緒に、そのときの体調や状況も記録しましょう。数値だけで良し悪しを判断せず、観察のための記録として扱います。', ARRAY['P08']::text[], '[{"issue_id":"I006","rule":"安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。"}]'::jsonb, '{}', ARRAY['呼吸数を観察する','セルフチェック','1分','記録','自分の呼吸を知るには？','呼吸数をどう数える？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP012', 'knowledge', 'K012', '胸やお腹の動きを観察する', 'observation', '息の通り道、胸やお腹の動き、肩や首の力みなどを観察します。
教材のチェック項目を、体の動きに気づくための観察として整理しました。「お腹が動かないから横隔膜が使えていない」などの診断には用いません。', ARRAY['P09','P157']::text[], '[{"issue_id":"I006","rule":"安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。"}]'::jsonb, '{}', ARRAY['胸やお腹の動きを観察する','胸郭','腹部','肩','鼻呼吸','呼吸のどこを観察する？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP013', 'knowledge', 'K013', '呼吸カルテに記録すること', 'observation', '呼吸数、鼻や口の呼吸、呼吸の感覚と、その日の睡眠・疲労感・気分などを記録します。
第1章の呼吸カルテと第5部のワークを別の様式として保存しています。記録は変化に気づく材料であり、記録だけで病気や原因を決めるものではありません。', ARRAY['P10','P27','P176','P190','P201','P205','P222']::text[], '[{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"}]'::jsonb, '{}', ARRAY['呼吸カルテに記録すること','カルテ','朝昼夜','気分','呼吸記録には何を書けばいい？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP014', 'knowledge', 'K014', 'プラーナとは', 'yoga_theory', 'プラーナは、ヨガで生命エネルギーを表すために使われる伝統的な考え方です。
教材では呼吸を通して心と体を整える文脈で扱っています。酸素やATPと同じ物質・測定値としては登録していません。', ARRAY['P15']::text[], '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"}]'::jsonb, '{}', ARRAY['プラーナとは','伝統的概念','プラーナ','プラーナは酸素のこと？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP015', 'knowledge', 'K015', 'プラーナーヤーマとは', 'yoga_theory', 'この教材では、呼吸に気づき、呼吸を意識的に整えるヨガの実践として説明しています。
長く息を止めたり、強く呼吸したりすることだけを指すのではありません。観察と無理のない実践を大切にしています。', ARRAY['P12','P15']::text[], '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"}]'::jsonb, '{}', ARRAY['プラーナーヤーマとは','呼吸への気づき','ヨガ','プラーナーヤーマとは？','ヨガの呼吸法は息止め？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP016', 'knowledge', 'K016', '初心者の息止めの扱い', 'safety', 'この教材の初心者向け実践は、息止めを入れない形を基本にしています。
ナディショーダナ簡易版では保息を入れません。ボックス呼吸や4-7-8呼吸の説明を、そのまま初心者用の実践指示にしないよう区別しています。', ARRAY['P16','P23','P26']::text[], '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"},{"issue_id":"I010","rule":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。"},{"issue_id":"I011","rule":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"}]'::jsonb, ARRAY['S004']::text[], ARRAY['初心者の息止めの扱い','初心者','保息','息止め','初心者も息を止める必要がある？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP017', 'knowledge', 'K017', 'ヨガ呼吸法と現代呼吸法を区別する', 'yoga_theory', 'この教材では、ヨガの体系に位置付ける呼吸法と、ボックス呼吸などの現代呼吸法を分けて整理しています。
優劣を決める分類ではありません。由来、実践の目的、教材での扱いを区別するための分類です。', ARRAY['P24','P26']::text[], '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"}]'::jsonb, '{}', ARRAY['ヨガ呼吸法と現代呼吸法を区別する','由来','比較','ボックス呼吸','4-7-8','ボックス呼吸は伝統的なヨガ？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP018', 'knowledge', 'K018', '実践を中止する目安と共通の注意', 'safety', '教材の共通ルールは、苦しくなるまで続けないこと、めまいが出たら中止することです。
不調を押して練習を続けません。慢性疾患・痛み・心臓の問題がある場合や妊娠中などは、教材の相談方針を確認してください。症状の診断や個別の実施可否を、このDBだけで判断しません。', ARRAY['P23','P29','P055']::text[], '[{"issue_id":"I010","rule":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。"},{"issue_id":"I011","rule":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。"}]'::jsonb, ARRAY['S004']::text[], ARRAY['実践を中止する目安と共通の注意','中止','めまい','苦しさ','呼吸法でめまいが出たら？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP019', 'knowledge', 'K019', '教材のCYP参照範囲', 'yoga_theory', '教材には、インド政府サイトのCommon Yoga Protocolへのリンクがあります。
引用先の版と教材の内容には照合が必要な箇所があります。特にシータリーの掲載説明は保留し、CYPに掲載されていると断定する回答には使いません。', ARRAY['P19','P24','P229']::text[], '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"}]'::jsonb, '{}', ARRAY['教材のCYP参照範囲','CYP','出典','版','この教材のCYPの出典は？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP020', 'knowledge', 'K020', '鼻の働き', 'physiology', '教材では鼻の働きを、ろ過・加温・加湿・嗅覚の4つに分けています。
空気の通り道を学ぶ項目です。鼻呼吸だけで病気を防げるという説明には広げません。', ARRAY['P030','P196','P208']::text[], '[{"issue_id":"I047","rule":"鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。"}]'::jsonb, '{}', ARRAY['鼻の働き','鼻','鼻呼吸','加温','加湿','鼻の働きとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP021', 'knowledge', 'K021', '副鼻腔とは', 'physiology', '副鼻腔は鼻のまわりの骨の中にある空洞です。
教材には一酸化窒素（NO）との関係も記載されていますが、集中力・免疫・運動効果までの説明は別途検証が必要です。', ARRAY['P031']::text[], '[{"issue_id":"I015","rule":"副鼻腔の構造の説明を残し、集中力・免疫・運動能力への効果は根拠確認まで別欄で保留する。"}]'::jsonb, '{}', ARRAY['副鼻腔とは','副鼻腔','NO','一酸化窒素','副鼻腔とはとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP022', 'knowledge', 'K022', '咽頭と喉頭の役割', 'physiology', '教材では、咽頭を空気と食べ物の通り道、喉頭を声と気管の保護に関わる場所として説明しています。
空気の流れと発声の学習をつなぐ項目です。', ARRAY['P032']::text[], '[]'::jsonb, '{}', ARRAY['咽頭と喉頭の役割','咽頭','喉頭','声帯','咽頭と喉頭の役割とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP023', 'knowledge', 'K023', '気管と気管支', 'physiology', '気管から左右の肺へ分かれる気管支は、さらに枝分かれして肺の中へ空気を届けます。
教材は粘液や線毛も紹介しています。構造の説明として扱います。', ARRAY['P033']::text[], '[]'::jsonb, '{}', ARRAY['気管と気管支','気管','気管支','線毛','気管と気管支とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP024', 'knowledge', 'K024', '肺胞とサーファクタント', 'physiology', '教材ではサーファクタントを、肺胞がつぶれにくくなるよう助けるものとして紹介しています。
肺胞の構造と働きの学習用です。', ARRAY['P035']::text[], '[]'::jsonb, '{}', ARRAY['肺胞とサーファクタント','肺胞','サーファクタント','肺胞とサーファクタントとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP025', 'knowledge', 'K025', '胸郭とは', 'physiology', '胸郭は、肋骨・胸骨・背骨で構成される胸のかご状の構造です。
胸郭の動きと呼吸を結び付けて学びます。安静時と力を入れて吐く場合の筋活動は区別します。', ARRAY['P036','P153']::text[], '[{"issue_id":"I016","rule":"安静時に吐く場合と、力を入れて吐く場合を分けて説明する。筋肉名と図の動作は監修後に確定する。"},{"issue_id":"I033","rule":"肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。"}]'::jsonb, '{}', ARRAY['胸郭とは','胸郭','肋骨','肋間筋','胸郭とはとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP026', 'knowledge', 'K026', '横隔膜とは', 'physiology', '横隔膜は胸とお腹を隔てるドーム状の筋肉です。吸うときに収縮して下がり、胸の空間を広げます。
横隔膜や肋骨の間の筋肉が胸の中の空間を動かすことで、肺が膨らみます。肺自身が筋肉として縮んで空気を吸い込むという意味ではありません。安静時に吐くときは横隔膜がゆるみます。', ARRAY['P037','P150']::text[], '[{"issue_id":"I017","rule":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。"}]'::jsonb, '{}', ARRAY['横隔膜とは','横隔膜','吸気','呼気','横隔膜とはとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP027', 'knowledge', 'K027', '死腔と肺胞換気', 'physiology', '吸った空気のすべてがガス交換に使われるわけではありません。教材はガス交換に直接参加しない空気の通り道を死腔として説明しています。
1回の量と回数の両方が肺胞に届く空気量に関係します。原図の500mL・1000mLなどは比較例であり、深く吸う練習の目標値にはしません。', ARRAY['P038']::text[], '[{"issue_id":"I017","rule":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。"},{"issue_id":"I018","rule":"この図は、死腔と肺胞換気を理解するための計算例です。呼吸を大きくする練習の目標値ではありません。"}]'::jsonb, '{}', ARRAY['死腔と肺胞換気','死腔','肺胞換気','1回換気量','死腔と肺胞換気とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP028', 'knowledge', 'K028', '肺循環と体循環', 'physiology', '肺循環は心臓と肺を結ぶ流れ、体循環は心臓と全身を結ぶ流れです。
教材は心臓を酸素の運搬を支えるポンプとして説明しています。', ARRAY['P040','P160','P164']::text[], '[{"issue_id":"I037","rule":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。"}]'::jsonb, '{}', ARRAY['肺循環と体循環','心臓','肺循環','体循環','肺循環と体循環とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP029', 'knowledge', 'K029', 'SpO₂の読み方', 'observation', 'SpO₂は、血液中のヘモグロビンと酸素の結び付きの割合を推定する指標です。
測定には誤差や限界があります。値だけで健康・不調を判定せず、症状や測定条件も含めて扱います。', ARRAY['P041','P158']::text[], '[{"issue_id":"I019","rule":"SpO₂の数値だけで健康状態を採点しません。測定条件や症状も含めて扱います。"},{"issue_id":"I035","rule":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。"}]'::jsonb, '{}', ARRAY['SpO₂の読み方','SpO₂','酸素飽和度','パルスオキシメータ','SpO₂の読み方とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP030', 'knowledge', 'K030', 'ミトコンドリアの構造', 'cell_energy', '教材では外膜・内膜・クリステ・マトリックスを紹介しています。クリステは内膜のひだです。
ATPの説明は共通知識に統合しています。', ARRAY['P042']::text[], '[]'::jsonb, '{}', ARRAY['ミトコンドリアの構造','ミトコンドリア','内膜','クリステ','マトリックス','ミトコンドリアの構造とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP031', 'knowledge', 'K031', '活性酸素の教材内での位置付け', 'cell_energy', '教材は、活性酸素を単に悪いものとせず、情報伝達や防御にも関係するものとして説明しています。
過剰な状態の説明と通常の働きを分けます。呼吸法や食品で老化を防ぐという保証には使いません。', ARRAY['P045']::text[], '[]'::jsonb, '{}', ARRAY['活性酸素の教材内での位置付け','活性酸素','酸化ストレス','活性酸素の教材内での位置付けとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP032', 'knowledge', 'K032', '交感神経と副交感神経', 'mind', '交感神経と副交感神経は、どちらも命を支える働きを持ちます。
教材は必要なときに状態を切り替えることを大切にしています。交感神経は悪い、副交感神経は常によい、とは扱いません。', ARRAY['P046','P173','P180','P181']::text[], '[{"issue_id":"I041","rule":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。"}]'::jsonb, '{}', ARRAY['交感神経と副交感神経','自律神経','交感神経','副交感神経','交感神経と副交感神経とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP033', 'knowledge', 'K033', 'HRVとは', 'observation', '心拍変動（HRV）は心臓の拍動の間隔が少しずつ変化することです。
教材でも、高ければ必ず健康、低ければ必ず不調とは判断しないとしています。呼吸・姿勢・活動・睡眠などの状況と一緒に扱います。', ARRAY['P047','P178','P185']::text[], '[{"issue_id":"I041","rule":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。"},{"issue_id":"I042","rule":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。"}]'::jsonb, '{}', ARRAY['HRVとは','HRV','心拍変動','R-R間隔','HRVとはとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP034', 'knowledge', 'K034', '長い呼気の考え方', 'mind', '教材では吸う息より吐く息を長くする練習を紹介しています。
苦しくなるまで長く吐く練習にはしません。秒数・回数は呼吸法カードに章ごとに保存しています。', ARRAY['P048','P175','P184']::text[], '[{"issue_id":"I022","rule":"基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。"},{"issue_id":"I041","rule":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。"},{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"}]'::jsonb, '{}', ARRAY['長い呼気の考え方','長い呼気','休息','長い呼気の考え方とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP035', 'knowledge', 'K035', '自動の呼吸と意識的な呼吸', 'mind', '教材は、延髄や橋などによる自動調整と、意識して呼吸を変える働きを説明しています。
呼吸は自動調整と意識的調整が交わる働きとして学びます。', ARRAY['P049','P193']::text[], '[]'::jsonb, '{}', ARRAY['自動の呼吸と意識的な呼吸','延髄','橋','呼吸中枢','自動の呼吸と意識的な呼吸とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP036', 'knowledge', 'K036', '呼吸を変えることが不安なとき', 'mind', '教材では、呼吸の操作が怖く感じられる場合は、まず呼吸を観察することから始めるとしています。
不安や息苦しさの原因をこの項目だけで決めません。強く深く吸うことを一律に求めません。', ARRAY['P050','P189']::text[], '[]'::jsonb, '{}', ARRAY['呼吸を変えることが不安なとき','不安','観察','パニック','呼吸を変えることが不安なときとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP037', 'knowledge', 'K037', '呼吸と集中の準備', 'mind', '教材は呼吸を集中へ戻るきっかけとして紹介しています。
呼吸をすれば必ずゾーンに入れるわけではない、と明記されています。練習・準備・経験と組み合わせて学ぶ位置付けです。', ARRAY['P051','P191','P197']::text[], '[{"issue_id":"I045","rule":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。"}]'::jsonb, '{}', ARRAY['呼吸と集中の準備','ゾーン','フロー','集中','呼吸と集中の準備とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP038', 'knowledge', 'K038', '眠ろうと頑張りすぎない', 'sleep', '教材では、眠るために呼吸を頑張りすぎず、楽な姿勢とやさしい呼吸を大切にします。
就寝前の呼吸法を不眠の診断や治療の代わりとして説明しません。', ARRAY['P052','P198']::text[], '[{"issue_id":"I026","rule":"名称案：就寝前のやさしい呼吸（第8章・保息なし）。原図の4秒吸う・7〜8秒吐くを記録し、7秒の保息は追加しない。"}]'::jsonb, '{}', ARRAY['眠ろうと頑張りすぎない','睡眠','就寝前','眠ろうと頑張りすぎないとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP039', 'knowledge', 'K039', '睡眠時無呼吸とは', 'sleep', '睡眠中に呼吸が何度も止まったり再開したりする状態を睡眠時無呼吸として扱います。
教材は上気道の閉塞に関係する型と、脳の呼吸調節に関係する型を区別しています。呼吸法だけで治るとは説明しません。', ARRAY['P053','P210','P211']::text[], '[{"issue_id":"I040","rule":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。"}]'::jsonb, '{}', ARRAY['睡眠時無呼吸とは','睡眠時無呼吸','OSA','CSA','睡眠時無呼吸とはとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP040', 'knowledge', 'K040', '睡眠の相談を専門家につなぐ目安', 'safety', '教材では、呼吸が止まると言われる、強いいびきが続く、日中の強い眠気があるなどの場合に医療機関への相談を勧める方針です。
呼吸マネージャーやAI先生が睡眠時無呼吸・不眠を診断するためのチェック表にはしません。', ARRAY['P054','P199','P205','P210']::text[], '[]'::jsonb, ARRAY['S004']::text[], ARRAY['睡眠の相談を専門家につなぐ目安','いびき','眠気','専門家','相談','睡眠の相談を専門家につなぐ目安とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP041', 'knowledge', 'K041', '回復のための呼吸の位置付け', 'conditioning', '教材では、休息へ向かうきっかけとして3分リカバリー呼吸を紹介しています。
多く吸うことや苦しいほど長く吐くことを目的にしません。疲労の原因を呼吸だけで決める項目ではありません。', ARRAY['P056','P213','P215','P175']::text[], '[{"issue_id":"I048","rule":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。"}]'::jsonb, '{}', ARRAY['回復のための呼吸の位置付け','疲労','回復','回復のための呼吸の位置付けとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP042', 'knowledge', 'K042', '冷えと呼吸の扱い', 'conditioning', '教材は、冷えに対して呼吸と生活習慣を一緒に振り返る考え方を紹介しています。
呼吸だけで体温が大きく上がる、冷えがすべて改善する、とは説明しません。', ARRAY['P057']::text[], '[]'::jsonb, '{}', ARRAY['冷えと呼吸の扱い','冷え','体温','生活習慣','冷えと呼吸の扱いとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP043', 'knowledge', 'K043', '運動直後の呼吸', 'conditioning', '教材では、運動直後に呼吸が大きく乱れている間は秒数を無理に合わせず、自然な呼吸から徐々に整えるとしています。
息苦しさ・めまい・胸の痛みがある場合は無理に続けず休むという注意を、実践カードにも保持しています。', ARRAY['P058']::text[], '[]'::jsonb, '{}', ARRAY['運動直後の呼吸','運動後','クールダウン','運動直後の呼吸とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP044', 'knowledge', 'K044', '腹式呼吸とお腹の動き', 'gut', '教材では腹式呼吸を、お腹だけを大きく動かす呼吸とは説明していません。
横隔膜に伴う自然なお腹の動きに気づく練習として紹介しています。無理にお腹を膨らませたり胸を押さえたりしません。', ARRAY['P059','P216']::text[], '[{"issue_id":"I048","rule":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。"}]'::jsonb, '{}', ARRAY['腹式呼吸とお腹の動き','腹式呼吸','横隔膜','腹部','腹式呼吸とお腹の動きとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP045', 'knowledge', 'K045', '腹圧とは', 'gut', '腹圧はお腹の中の圧力です。教材では姿勢・体幹の支えと関わるものとして扱います。
腹圧は高ければよいとは説明せず、必要なときに支え、不要なときにはゆるめることを学びます。', ARRAY['P060']::text[], '[]'::jsonb, '{}', ARRAY['腹圧とは','腹圧','体幹','骨盤底','腹圧とはとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP046', 'knowledge', 'K046', '腸脳相関とは', 'gut', '腸と脳が神経・ホルモン・免疫などを通じて互いに影響し合う関係を、教材では腸脳相関と呼んでいます。
呼吸だけですべての腸の不調が解決するとは説明しません。', ARRAY['P061','P216']::text[], '[{"issue_id":"I048","rule":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。"}]'::jsonb, '{}', ARRAY['腸脳相関とは','腸脳相関','腸','脳','腸脳相関とはとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP047', 'knowledge', 'K047', '食前と食後の使い分け', 'gut', '教材では食前は落ち着いて食事に入る準備、食後は体を休める場面として区別しています。
便秘や胃腸の不調の改善を保証する目的タグにはしません。', ARRAY['P062']::text[], '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]'::jsonb, '{}', ARRAY['食前と食後の使い分け','食前','食後','休息','食前と食後の使い分けとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP048', 'knowledge', 'K048', '生活に呼吸を取り入れる', 'lifestyle', '教材は朝・昼・夜など、生活の中で呼吸に気づく時間を決める方法を紹介しています。
最初からすべてを行うのではなく、取り入れやすい場面から始めるという学習方針です。', ARRAY['P063','P217','P218','P200']::text[], '[]'::jsonb, '{}', ARRAY['生活に呼吸を取り入れる','生活習慣','朝','昼','夜','生活に呼吸を取り入れるとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP049', 'knowledge', 'K049', 'アーユルヴェーダの教材内での扱い', 'lifestyle', 'この教材ではアーユルヴェーダを、インドで発展した伝統的な健康観として紹介しています。
食事・睡眠・季節・生活リズムを一緒に見る考え方として学び、医学的な診断や治療には用いません。', ARRAY['P064','P217']::text[], '[]'::jsonb, '{}', ARRAY['アーユルヴェーダの教材内での扱い','アーユルヴェーダ','伝統','生活','アーユルヴェーダの教材内での扱いとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP050', 'knowledge', 'K050', 'ドーシャをどう扱うか', 'lifestyle', '教材はヴァータ・ピッタ・カパを、自分の傾向や今日の状態を振り返る伝統的な枠組みとして紹介しています。
医学的な診断名や固定的な人物分類にはしません。分類だけを理由に呼吸法を自動処方しない設計です。', ARRAY['P065']::text[], '[]'::jsonb, '{}', ARRAY['ドーシャをどう扱うか','ドーシャ','ヴァータ','ピッタ','カパ','ドーシャをどう扱うかとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP051', 'knowledge', 'K051', '本番で呼吸を使う4つの目的', 'performance', '教材は本番前の準備、ミス後の切り替え、動作とのリズム、力を出す場面を分けています。
場面ごとの技法を混ぜず、競技成績や成功を保証する説明には使いません。', ARRAY['P066','P220']::text[], '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]'::jsonb, '{}', ARRAY['本番で呼吸を使う4つの目的','本番前','切り替え','動作','力発揮','本番で呼吸を使う4つの目的とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP052', 'knowledge', 'K052', '競技による呼吸の違い', 'performance', '教材では持久系・パワー系・間欠ダッシュ系・精密集中系・水中系の課題を分けています。
水中の実践や強い負荷の運動へ、日常向けの呼吸手順を自動転用しません。', ARRAY['P067','P221']::text[], '[]'::jsonb, '{}', ARRAY['競技による呼吸の違い','スポーツ','競技','持久','パワー','競技による呼吸の違いとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP053', 'knowledge', 'K053', '試合の前・中・後の使い分け', 'performance', '教材では試合前は準備、試合中は動作や判断への復帰、試合後は徐々に落ち着くことを目的にしています。
各場面を個別カードの参照先として保持します。', ARRAY['P068']::text[], '[]'::jsonb, '{}', ARRAY['試合の前・中・後の使い分け','試合前','試合中','試合後','試合の前・中・後の使い分けとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP054', 'knowledge', 'K054', '声と呼気', 'voice', '教材では呼気が声帯を通るときの振動を、声が生まれる基本として説明しています。
声には呼吸・声帯・共鳴・発音などが関係します。「声の質のすべてが呼吸で決まる」とは説明しません。胸や頭に感じる響きと解剖学的な共鳴腔の区別は監修対象です。', ARRAY['P069','P223']::text[], '[{"issue_id":"I049","rule":"声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。"}]'::jsonb, '{}', ARRAY['声と呼気','声','声帯','呼気','声と呼気とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP055', 'knowledge', 'K055', 'お腹から声を出すという表現', 'voice', 'お腹から直接声が出るという意味ではありません。教材では呼吸や体の支えによって声を支えるという意味で使っています。
お腹を強く固めたり、喉で押し出したりする指示にはしません。', ARRAY['P070']::text[], '[]'::jsonb, '{}', ARRAY['お腹から声を出すという表現','腹圧','声','横隔膜','お腹から声を出すという表現とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
