症状が続く場合の専門家への相談方針を保持しています。病気の診断や練習の続行判断はしません。', ARRAY['P071']::text[], '[{"issue_id":"I028","rule":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。"}]'::jsonb, ARRAY['S004']::text[], ARRAY['声の練習を中止する目安','声枯れ','喉','痛み','声の練習を中止する目安とは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP057', 'knowledge', 'K057', '落ち着く・集中する・切り替える', 'performance', '教材は本番で呼吸を使う目的を、落ち着く、集中する、切り替えるなどに分けています。
呼吸ですべての練習が不要になるとは説明しません。同名技法の秒数差は別の手順として保持します。', ARRAY['P072','P225','P226','P228']::text[], '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]'::jsonb, '{}', ARRAY['落ち着く・集中する・切り替える','メンタル','本番','目的','落ち着く・集中する・切り替えるとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP058', 'knowledge', 'K058', '本番前のルーティンを考える', 'performance', '教材は学生と社会人それぞれの場面に合わせ、姿勢・呼吸・自分にかける言葉を準備する方法を紹介しています。
学生向け3分、社会人向け1分という例は教材の例として保存し、年齢だけで自動適用しません。', ARRAY['P073','P188','P227','P222']::text[], '[{"issue_id":"I044","rule":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。"}]'::jsonb, '{}', ARRAY['本番前のルーティンを考える','試験','プレゼン','ルーティン','本番前のルーティンを考えるとは？']::text[], false, true) ON CONFLICT (retrieval_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES ('RP059', 'knowledge', 'K059', 'ヨガをどう学ぶか', 'yoga_theory', 'この教材ではヨガを、身体・呼吸・心・生活・集中・瞑想を含む体系として学びます。
